Lemma ALSR_transport : forall W m m' ls,
  ALSR m ls -> munch W m m' -> wmono bsegs m m' -> Forall awin W ->
  (forall a n, ls !! a = Some n -> disjoint_from W a 16) -> ALSR m' ls.
Proof.
  intros W m m' ls (LC & SEP & LA) MU WM FW D. split; [| split; [exact SEP| eapply LAcc_transport; eauto]].
  eapply ALSCells_transport; eauto.
Qed.

(* [comment removed for export] *)
Lemma addressable_transport_awin : forall W m m' A n,
  addressable m A n -> munch W m m' -> wmono bsegs m m' -> Forall awin W -> A + n <= AAPP_HI -> addressable m' A n.
Proof.
  intros W m m' A n AD MU WM FW Htop. pose proof AD as (Hn & A0 & _).
  eapply addressable_transport; [exact AD| exact MU| exact WM|].
  apply awin_disjoint_shland; [exact FW| apply sh_ge_lowsh; lia| apply sh_nsh_high; lia].
Qed.

Lemma AEMShad_transport_awin : forall W m m' em,
  AEMShad m em -> em_ok em -> munch W m m' -> wmono bsegs m m' -> Forall awin W -> AEMShad m' em.
Proof.
  intros W m m' em SH EOK MU WM FW e d L. pose proof (em_ok_aapp _ _ _ EOK L) as AP. pose proof (esize_ge d) as SG.
  pose proof (aapp_bounds _ _ AP ltac:(lia)) as (B1 & B2 & B3 & B4 & B5).
  eapply addressable_transport_awin; [exact (SH e d L)| exact MU| exact WM| exact FW| lia].
Qed.

Lemma AHdrA_transport_awin : forall W m m' h, AHdrA m h -> munch W m m' -> Forall awin W -> AHdrA m' h.
Proof.
  intros W m m' h (AP & AL & AC) MU FW. split; [exact AP|]. split; [exact AL|]. eapply accessible_transport_awin; eauto.
Qed.
End LSRdef.

Lemma lb_load {R} (ls : LS) x off nd (K : Z -> option R) r :
  ls !! x = Some nd -> (lload ls x off ≫= K) = Some r -> K (lget_field off nd) = Some r.
Proof. intros L H. unfold lload in H. rewrite L in H. exact H. Qed.
Lemma lb_store {R} (ls : LS) x off v nd (K : LS -> option R) r :
  ls !! x = Some nd -> (lstore ls x off v ≫= K) = Some r -> K (<[x := lset_field off v nd]> ls) = Some r.
Proof. intros L H. unfold lstore in H. rewrite L in H. exact H. Qed.
Lemma l_store_last (ls : LS) x off v nd r : ls !! x = Some nd -> lstore ls x off v = Some r -> r = <[x := lset_field off v nd]> ls.
Proof. intros L H. unfold lstore in H. rewrite L in H. cbn in H. congruence. Qed.

(* [comment removed for export] *)
Lemma lstore_swap_np {R} (ls : LS) x v w (K : LS -> option R) :
  (set_next ls x v ≫= λ ls1, set_prev ls1 x w ≫= K) = (set_prev ls x w ≫= λ ls1, set_next ls1 x v ≫= K).
Proof.
  unfold set_next, set_prev, lstore. destruct (ls !! x) as [n|] eqn:L; [| reflexivity].
  cbn [mbind option_bind]. rewrite !lookup_insert_eq. cbn [mbind option_bind]. rewrite !insert_insert_eq.
  unfold lset_field, OFF_NEXT, OFF_PREV, l_set_next, l_set_prev. cbn. reflexivity.
Qed.

Lemma lstore_swap {R} (ls : LS) x v w (K : LS -> option R) :
  (lstore ls x OFF_NEXT v ≫= λ ls1, lstore ls1 x OFF_PREV w ≫= K) = (lstore ls x OFF_PREV w ≫= λ ls1, lstore ls1 x OFF_NEXT v ≫= K).
Proof. exact (lstore_swap_np ls x v w K). Qed.

(* [comment removed for export] *)
Ltac shchk_load2 RD :=
  zstep; step; clear RD;
  try replace (zxb (b8 0)) with (Z_to_bv 64 0) by (apply bv_eq; vm_compute; reflexivity);
  try replace (sxb (b8 0)) with (Z_to_bv 64 0) by (apply bv_eq; vm_compute; reflexivity).

(* [comment removed for export] *)
Ltac lnode LSRH L CH :=
  let WF := fresh "WF" in let B := fresh "B" in let OUT := fresh "OUT" in
  destruct (ALSR_node _ _ _ _ LSRH L) as (WF & OUT & CH);
  unfold lnode_wf in WF; unfold LNodeCells, wz in CH;
  pose proof (rw_cells_bound _ _ _ _ CH) as B; cbn [cells_size csize Nat.add] in B.

Ltac lmnode ls x nd L H :=
  destruct (ls !! x) as [nd|] eqn:L;
  [| exfalso; unfold get_next, get_prev, set_next, set_prev, lload, lstore in H;
     rewrite L in H; cbn [mbind option_bind] in H; discriminate].

Ltac lmstep H L :=
  first [ apply (lb_store _ _ _ _ _ _ _ L) in H | apply (lb_load _ _ _ _ _ _ L) in H
        | apply (l_store_last _ _ _ _ _ _ L) in H ];
  cbn [lget_field lset_field OFF_NEXT OFF_PREV Z.eqb Pos.eqb l_set_next l_set_prev l_next l_prev] in H.

Ltac lpost_store LSRk Lx ML WL CH n' k w :=
  let WFn := fresh "WFn" in
  assert (WFn : lnode_wf n') by (unfold lnode_wf; cbn [l_next l_prev l_set_next l_set_prev]; lia);
  let N := fresh "LSR" in
  pose proof (ALSR_store _ _ _ _ _ n' k w LSRk Lx ML WL ltac:(lia) ltac:(lia) WFn CH) as N;
  clear LSRk ML WL CH WFn; rename N into LSRk.

Ltac lgen_store LSRk :=
  lazymatch type of LSRk with ALSR _ ?lsk =>
    let lsv := fresh "ls" in let E := fresh "Els" in remember lsk as lsv eqn:E; clear E end.

(* [comment removed for export] *)
Ltac lload_step LSRk H x :=
  lazymatch type of LSRk with ALSR _ ?ls =>
    let nd := fresh "ln" in let L := fresh "L" in let CH := fresh "CH" in
    lmnode ls x nd L H; lmstep H L; lnode LSRk L CH; step; clear CH;
    try match goal with B : 0 <= x /\ x + Z.of_nat 16 <= 2^64 |- _ => clear B end
  end.

(* [comment removed for export] *)
Ltac lstore_step LSRk H x k mk :=
  lazymatch type of LSRk with ALSR _ ?ls =>
    let nd := fresh "ln" in let L := fresh "L" in let CH := fresh "CH" in let ML := fresh "ML" in let WL := fresh "WL" in
    lmnode ls x nd L H; lmstep H L; lnode LSRk L CH; pre_store CH k 8 ML WL; st1;
    let nd' := eval cbv beta in (mk nd) in
    lpost_store LSRk L ML WL CH nd' k 8; lgen_store LSRk; clear L;
    try match goal with B : 0 <= x /\ x + Z.of_nat 16 <= 2^64 |- _ => clear B end
  end.

(* [comment removed for export] *)
Ltac lchk LSRk Lx k := let RD := fresh "RD" in pose proof (ALSR_rd _ _ _ _ k LSRk Lx ltac:(lia)) as RD; shchk_fast RD.
Ltac lchk_ld LSRk Lx k := let RD := fresh "RD" in pose proof (ALSR_rd _ _ _ _ k LSRk Lx ltac:(lia)) as RD; shchk_load RD.

