Section Pure.
  Context {K : Type} (lt : K -> K -> bool) (key key' : Z -> K).

  Lemma sorted_ext : forall S, (forall x, x ∈ S -> key x = key' x) -> sorted lt key S -> sorted lt key' S.
  Proof.
    induction S as [|a S IH]; intros AG HS; [exact I|]. cbn in HS |- *. destruct HS as [H1 H2]. split.
    - intros b Hb. rewrite <- (AG a), <- (AG b) by (rewrite elem_of_cons; auto). apply H1. exact Hb.
    - apply IH; [| exact H2]. intros x Hx. apply AG. rewrite elem_of_cons. right; exact Hx.
  Qed.
