Definition LINKB_STACK : Z := 16.

Definition linkb_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (ls' : LS) (lo nxt e prv : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom bsegs)
    /\ munch [(lo, bv_unsigned sp); (e, e + 16); (nxt, nxt + 16); (prv, prv + 16)]%Z m m' /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ stk bsegs m' lo (bv_unsigned sp)
    /\ ALSR m' ls' /\ ACONST m'.

Definition linkb_stmt : Prop := forall (nxt e prv : Z) (ls ls' : LS) (lo : Z) (ndn : lnode)
    ra sp gp tp t0 t1 t2 s0 s1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  ALSR m ls -> ls !! nxt = Some ndn -> l_prev ndn = prv -> is_Some (ls !! e) -> is_Some (ls !! prv) ->
  link_before ls nxt e = Some ls' ->
  stk bsegs m lo (bv_unsigned sp) -> lo + LINKB_STACK <= bv_unsigned sp -> aceil <= lo ->
  mem_inv bsegs m -> ACONST m ->
  evt bsegs (linkb_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc ls' lo nxt e prv m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (wz nxt) (wz e) a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_B_LINK_BEFORE) fc None m (seg_rom bsegs)).

