(* [comment removed for export] *)
Lemma insW_awin : forall m Fa S L ns ls em e d lo hi,
  AFieldsC m Fa S L ns ls em -> new_elt_ok Fa em e d -> aceil <= lo -> Forall awin (insW lo hi Fa (e :: L)).
Proof.
  intros m Fa S L ns ls em e d lo hi FC NEW CE.
  pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS).
  pose proof NEW as (EP & EAL & EHI & WFd & EAP & EA8 & DJ & HSE). pose proof (esize_ge d) as EG.
  unfold insW. apply Forall_cons; [apply awin_stack; exact CE|].
  apply Forall_cons; [destruct HA as (AP & _); eapply awin_aapp; [exact AP| lia| lia]|].
  cbn [elemsW map]. apply Forall_cons; [eapply awin_aapp; [exact EAP| lia| lia]|].
  apply Forall_forall. intros iv IN. apply in_map_iff in IN. destruct IN as (x & <- & IN).
  apply (proj2 (list_elem_of_In _ _)) in IN. apply LE in IN. destruct IN as [dx Lx].
  pose proof (esize_ge dx). eapply awin_aapp; [exact (em_ok_aapp _ _ _ EOK Lx)| lia| lia].
Qed.


(* [comment removed for export] *)
(* [comment removed for export] *)

Section IE.
  Variables (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32).
  Variables (m : mem) (Fa e f : Z) (name value pad tail : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt).
  Variables (lo shi : Z) (junk : list byte).
  Let d := mkElt f name value pad tail.
  Hypothesis FC : AFieldsC m Fa S L ns ls em.
  Hypothesis NEW : new_elt_ok Fa em e d.
  Hypothesis LO : lo + INSEL_STACK <= bv_unsigned sp.
  Hypothesis CEIL : aceil <= lo.
  (* [comment removed for export] *)
  Hypothesis SPAL : bv_unsigned sp mod 16 = 0.
  Hypothesis AC : ACONST m.
  Hypothesis SK : stack0 m lo shi.
  Hypothesis SHI : bv_unsigned sp <= shi.
  Hypothesis ADE : addressable m e (esize d).
  Hypothesis SVE : shvis m (e + 16) (e + 48).

  Let kb := zbytes name.
  Let key := key_of em.
  Let ubA := ub_prefix key_lt key kb S.
  Let ubB := ub_suffix key_lt key kb S.
  Let before := lhead Fa ubB.
  Let fuel := Datatypes.S (length S).
  Let X := Fa :: (e + 16) :: S.

  (* [comment removed for export] *)
  Definition ie_mem (m1 : mem) (j8 : list byte) (w8 w16 : word) : Prop :=
    rw_cells bsegs m1 (bv_unsigned sp + -96) [CB 8 j8]
    /\ rw_cells bsegs m1 (bv_unsigned sp + -88) [C8 w8; C8 w16]
    /\ rw_cells bsegs m1 (bv_unsigned sp + -72) [C8 (Z_to_bv 64 Fa); C8 s6; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ rw_cells bsegs m1 e [CB 48 junk] /\ rw_cells bsegs m1 (e + 48) (ValCells d) /\ bytes_at bsegs m1 (e + 56) name
    /\ munch (insW lo (bv_unsigned sp) Fa (e :: L)) m m1 /\ munch [(lo, bv_unsigned sp)]%Z m m1 /\ wmono bsegs m m1
    /\ mem_inv bsegs m1 /\ stk bsegs m1 lo (bv_unsigned sp + -96).

  (* [comment removed for export] *)
  Local Ltac ie_pure :=
    pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
    pose proof aceil_facts as (AF1 & AF2 & AF3); pose proof (stack0_bounds _ _ _ SK) as [SKB1 SKB2]; unfold AAPP_HI in SKB2;
    unfold INSEL_STACK, IB_STACK, ICOMMIT_STACK, AINTRIN_STACK in LO;
    pose proof FC as (NC & LC & EC & OK & SO & DL & SL & LE & EOK & ESH & HA & HS);
    pose proof (AHdrA_bounds _ _ HA) as (HB1 & HB2 & HB3 & HB4 & HAL); unfold AIMG_TOP in HB1;
    pose proof NEW as (EP & EAL & EHI & WFd & EAP & EA8 & DJ & HSE);
    destruct (new_elt_fresh _ _ _ _ _ _ _ _ _ FC NEW) as (NONE & NL & NS & NEF & NE0 & E0 & KAG & KNEW & EOK' & HS');
    pose proof (rb_ok_rep _ _ _ OK) as RR; pose proof (rb_rep_nodup _ _ _ RR) as ND;
    pose proof (ub_split key_lt key kb S : S = ubA ++ ubB) as ES;
    unfold elt_wf, esize in EHI, WFd, EA8; cbn [d el_f el_name el_value el_pad el_tail] in EHI, WFd, EA8;
    unfold zlength in WFd, EHI, EA8;
    assert (EG : esize d = 60 + Z.of_nat (length name) + Z.of_nat (length value) + Z.of_nat (length tail)) by reflexivity;
    pose proof (insW_awin _ _ _ _ _ _ _ _ _ lo (bv_unsigned sp) FC NEW CEIL) as FWI.

  Local Ltac ie_open M :=
    destruct M as (FR0 & KV & FRH & HK & PL & NB & MU & MUf & WM & MI & ST);
    pose proof (rw_cells_bound _ _ _ _ PL) as PLB; rewrite ValCells_size in PLB; unfold esize in PLB;
    cbn [d el_f el_name el_value el_pad el_tail] in PLB; unfold zlength in PLB;
    unfold ValCells in PL; cbn [d el_f el_name el_value el_pad el_tail] in PL; unfold wz in PL; unfold zlength in PL.

  (* [comment removed for export] *)
  Lemma ie_X_facts :
    (forall x, x ∈ X -> x + 32 <= lo \/ bv_unsigned sp <= x)
    /\ (forall x, x ∈ X -> x = Fa \/ x = e + 16 \/ (exists dx, em !! (x - 16) = Some dx /\ (e + esize d <= x - 16 \/ x - 16 + esize dx <= e)))
